CREATE OR REPLACE FUNCTION public.keep_legacy_verification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.verified:=false; ELSE NEW.verified:=OLD.verified; END IF; RETURN NEW; END; $$;
CREATE TRIGGER zz_preserve_verification BEFORE INSERT OR UPDATE ON public.businesses FOR EACH ROW EXECUTE FUNCTION public.keep_legacy_verification();
CREATE OR REPLACE FUNCTION public.validate_report_rate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtext(NEW.reporter_id::text)); IF (SELECT count(*) FROM public.review_reports WHERE reporter_id=NEW.reporter_id AND created_at>now()-interval '1 hour')>=10 THEN RAISE EXCEPTION 'Report rate limit reached'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER report_rate_guard BEFORE INSERT ON public.review_reports FOR EACH ROW EXECUTE FUNCTION public.validate_report_rate();
CREATE OR REPLACE FUNCTION public.moderate_review(review_id uuid,hide boolean,decision_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.reviews; BEGIN SELECT * INTO r FROM public.reviews WHERE id=review_id FOR UPDATE; IF NOT FOUND OR NOT public.has_permission('reviews.moderate',r.business_id) OR length(trim(decision_reason))<5 THEN RAISE EXCEPTION 'Moderation permission and reason required'; END IF; PERFORM set_config('app.trust_review','true',true); PERFORM set_config('app.trust_reason',decision_reason,true); UPDATE public.reviews SET status=CASE WHEN hide THEN 'hidden' ELSE 'published' END,moderation_reason=decision_reason WHERE id=review_id; END; $$;
GRANT EXECUTE ON FUNCTION public.moderate_review(uuid,boolean,text) TO authenticated; REVOKE EXECUTE ON FUNCTION public.moderate_review(uuid,boolean,text) FROM PUBLIC,anon;
CREATE POLICY "review author sees own report decisions" ON public.review_reports FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.reviews r WHERE r.id=review_id AND r.user_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.validate_staff_scope() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.city IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.directory_locations WHERE kind='city' AND name=NEW.city AND active) THEN RAISE EXCEPTION 'Unknown city scope'; END IF; IF NEW.category IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.directory_categories WHERE active AND (slug=NEW.category OR legacy_slug=NEW.category)) THEN RAISE EXCEPTION 'Unknown category scope'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER staff_scope_guard BEFORE INSERT OR UPDATE ON public.staff_assignments FOR EACH ROW EXECUTE FUNCTION public.validate_staff_scope();